// throatArt.js — Rurik's THROAT CUT poses (ChatGPT, Nov 2026; FINISHERS.throat in
// combat/Finisher.js), baked into the HD sheet format by tools/bake-grab-strip.py. Kept out
// of heroHdAssets.js (that file is regenerated by tools/compile-hero-hd.mjs on the PC) and
// added to it by view/heroHd.js, like data/grabArt.js. Poses (anims fin_throatCut,
// data/spriteStrips.js): 0 the lunge, 1 the seize, 2 the edge set under his chin, 3 ripped
// across, 4 holding him, 5 the shove, 6 the blood flicked off, 7 standing over him.
const sheet = (key, file) => ({ id: `rurik-${key}-finCut`, hero: 'rurik', key, name: 'finCut', file: `assets/sprites/heroes-hd/${file}`, frames: 8, fw: 696, fh: 480, cols: 4, originX: 0.5, originY: 460 / 480, swords: [] });
export const THROAT_SHEETS = [
  sheet('ulric', 'rurik-ulric-finCut.png'),
  sheet('ulricOath', 'rurik-ulricOath-finCut.png'),
];

// THE HOLD, PAINTED AS ONE PICTURE (Nick, 2026-11-05 "looks rough in all aspects": two
// separate figures never touched — Rurik's fist punched the air beside the man's head).
// One ChatGPT strip per enemy and sword, Rurik and the man together: 0 seized from behind,
// head hauled back, 1 the flat of the blade across his neck, 2 drawn through, 3 shoved
// off. While it plays the man's own sprite is hidden (view/SpriteEnemyView.js); from the
// shove on he's himself again (his _throat strip: stagger, knees, over). Rurik's feet are
// the origin; `release` = how far in front of Rurik's feet (world px) the man stands in
// pose 3, where his own sprite takes over.
// neck: where his throat is in the hold, world px in front of Rurik's feet (the cut's
// blood comes out of the picture there, not out of his hidden sprite).
export const PAIR_DRAWN = {
  // <enemy art id>: which of Rurik's two swords are painted, release, neck
  grunt: { ulric: 0.5, ulricOath: 0.5, release: 51, neck: 22 },
  stalker: { ulric: 0.5, ulricOath: 0.5, release: 51, neck: 22 },
  butcher: { ulric: 0.5, ulricOath: 0.5, release: 43, neck: 22 },
  ghoul: { ulric: 0.5, ulricOath: 0.5, release: 53, neck: 22 },
  penitent: { ulric: 0.5, ulricOath: 0.5, release: 61, neck: 26 },
  berserker: { ulric: 0.5, ulricOath: 0.5, release: 46, neck: 22 },
  gladiator: { ulric: 0.5, ulricOath: 0.5, release: 47, neck: 22 },
};
// THE THROAT in the hold: where Rurik's blade crosses the front of the man's neck, in the
// picture's own pixels (one 696x480 cell; the same spot with either sword). The cut's
// blood comes out of exactly there (view/throatPoint.js).
export const PAIR_THROAT = {
  grunt: [409, 270], stalker: [407, 272], butcher: [395, 272], ghoul: [395, 267],
  penitent: [403, 257], berserker: [395, 267], gladiator: [392, 268],
};

// Grunts come in dyes (view/dye.js) and the picture has him undyed: their strips carry a
// second row (frames 4-7, tools/bake-pair-dye-mask.py), just his rags, which the game lays
// over the picture through the dye shader in his dye (view/SpriteFighterView.js).
export const DYED = ['grunt'];
const pair = (key, id, originX) => ({ id: `rurik-${key}-pair-${id}`, hero: 'rurik', key, name: `pair_${id}`, file: `assets/sprites/heroes-hd/rurik-${key}-pair-${id}.png`, frames: DYED.includes(id) ? 8 : 4, fw: 696, fh: 480, cols: 4, originX, originY: 460 / 480, swords: [] });
for (const [id, m] of Object.entries(PAIR_DRAWN)) for (const key of ['ulric', 'ulricOath']) if (m[key] != null) THROAT_SHEETS.push(pair(key, id, m[key]));
